+import { Type } from "class-transformer";
+import {
+  ArrayMinSize,
+  IsArray,
+  IsIn,
+  IsOptional,
+  IsString,
+  IsUrl,
+  IsUUID,
+  ValidateNested,
+} from "class-validator";
+
+class ImportDocumentDto {
+  @IsString()
+  title!: string;
+
+  @IsOptional()
+  @IsUrl({ require_tld: false })
+  url?: string;
+}
+
+class ImportItemReviewDto {
+  @IsUUID()
+  itemId!: string;
+
+  @IsIn(["confirmed", "edited", "needs-doc"])
+  technicianDecision!: "confirmed" | "edited" | "needs-doc";
+
+  @IsOptional()
+  @IsString()
+  technicianNotes?: string;
+
+  @IsOptional()
+  @IsString()
+  normalizedName?: string;
+
+  @IsOptional()
+  @IsString()
+  category?: string;
+
+  @IsArray()
+  @ValidateNested({ each: true })
+  @Type(() => ImportDocumentDto)
+  documents!: ImportDocumentDto[];
+}
+
+export class ReviewImportBatchDto {
+  @IsArray()
+  @ArrayMinSize(1)
+  @ValidateNested({ each: true })
+  @Type(() => ImportItemReviewDto)
+  items!: ImportItemReviewDto[];
+}

