+import { createOpenAI } from "@ai-sdk/openai";
+import { Injectable, Logger } from "@nestjs/common";
+import { ConfigService } from "@nestjs/config";
+import { generateObject } from "ai";
+import { z } from "zod";
+
+const matchSchema = z.object({
+  matches: z.array(
+    z.object({
+      itemId: z.string().uuid(),
+      normalizedName: z.string(),
+      category: z.string(),
+      confidence: z.number().min(0).max(100),
+      reasoning: z.string(),
+      candidates: z.array(
+        z.object({
+          label: z.string(),
+          confidence: z.number().min(0).max(100),
+          notes: z.string(),
+        })
+      ),
+    })
+  ),
+});
+
+interface MatchInput {
+  id: string;
+  rawPayload: Record<string, unknown>;
+  sku: string;
+  vendor: string;
+}
+
+@Injectable()
+export class ImportMatchingService {
+  private readonly logger = new Logger(ImportMatchingService.name);
+
+  constructor(private readonly configService: ConfigService) {}
+
+  async matchItems(items: MatchInput[]) {
+    const apiKey = this.configService.get<string>("ai.openAiApiKey");
+    if (!apiKey) {
+      this.logger.warn("OPENAI_API_KEY missing. Falling back to deterministic hackathon matcher.");
+      return this.matchItemsFallback(items);
+    }
+
+    const modelName = this.configService.get<string>("ai.model", "gpt-4.1-mini");
+    const openai = createOpenAI({ apiKey });
+
+    const result = await generateObject({
+      model: openai(modelName),
+      schema: matchSchema,
+      prompt: [
+        "You match raw data center hardware SKUs into canonical component names.",
+        "Return one match per item.",
+        "Keep category values concise and operations-friendly.",
+        "Use ingress metadata when SKU alone is ambiguous.",
+        JSON.stringify(items),
+      ].join("\n\n"),
+    });
+
+    return result.object.matches;
+  }
+
+  private matchItemsFallback(items: MatchInput[]) {
+    return items.map((item) => {
+      const category = this.resolveCategory(item.sku);
+      const normalizedName = `${item.vendor} ${item.sku.split("-").join(" ")}`;
+      const confidence = item.sku.includes("HGX") ? 74 : item.sku.includes("PDU") ? 89 : 93;
+
+      return {
+        itemId: item.id,
+        normalizedName,
+        category,
+        confidence,
+        reasoning: `Fallback matcher translated ${item.sku} into ${category.toLowerCase()} using SKU token parsing and ingress metadata.`,
+        candidates: [
+          {
+            label: normalizedName,
+            confidence,
+            notes: "Best deterministic vendor match",
+          },
+          {
+            label: `${item.vendor} ${category.toLowerCase()} variant`,
+            confidence: 48,
+            notes: "Fallback family variant",
+          },
+        ],
+      };
+    });
+  }
+
+  private resolveCategory(sku: string) {
+    if (sku.includes("PDU")) return "Power Distribution";
+    if (sku.includes("N9K")) return "Network Fabric";
+    if (sku.includes("CRV")) return "Cooling Infrastructure";
+    if (sku.includes("HGX") || sku.includes("GPU")) return "Accelerated Compute";
+    return "Facility Component";
+  }
+}

