+} as const;
+
+function Panel({ title, subtitle, children }: { children: ReactNode; subtitle: string; title: string }) {
+  return (
+    <section className="rounded-[24px] border border-white/[0.06] bg-[#0a0a0a] shadow-[inset_0_1px_0_rgba(255,255,255,0.04)]">
+      <div className="border-b border-white/[0.06] px-5 py-4">
+        <p className="text-[10px] uppercase tracking-[0.16em] text-zinc-600">{subtitle}</p>
+        <h2 className="mt-1 text-[18px] font-semibold text-white">{title}</h2>
+      </div>
+      <div className="px-5 py-5">{children}</div>
+    </section>
+  );
+}
+
+function getErrorMessage(error: unknown) {
+  if (error instanceof Error) return error.message;
+  return "Request failed";
+}
+
+export default function ImportFlow() {
+  const [step, setStep] = useState<WizardStep>(1);
+  const [batch, setBatch] = useState<BatchResponse | null>(null);
+  const [selectedId, setSelectedId] = useState("");
+  const [draftDocs, setDraftDocs] = useState<Record<string, string[]>>({});
+  const [draftDocInput, setDraftDocInput] = useState("");
+  const [draftNotes, setDraftNotes] = useState<Record<string, string>>({});
+  const [draftDecision, setDraftDecision] = useState<Record<string, TechnicianDecision>>({});
+  const [draftName, setDraftName] = useState<Record<string, string>>({});
+  const [draftCategory, setDraftCategory] = useState<Record<string, string>>({});
+  const [commitResult, setCommitResult] = useState<CommitResponse | null>(null);
+  const [errorMessage, setErrorMessage] = useState<string | null>(null);
+  const [loading, setLoading] = useState<"pull" | "match" | "review" | "commit" | null>(null);
+
+  const rows = batch?.items ?? [];
+  const selectedRow = useMemo(
+    () => rows.find((row) => row.id === selectedId) ?? rows[0] ?? null,
+    [rows, selectedId]
+  );
+
+  const step1Complete = Boolean(batch && batch.items.length > 0);
+  const step2Complete = rows.length > 0 && rows.every((row) => row.normalizedName && row.candidates.length > 0);
+  const step3Complete = rows.length > 0 && rows.every((row) => {
+    const docs = draftDocs[row.id] ?? row.documents.map((document) => document.title);
+    const decision = draftDecision[row.id] ?? row.technicianDecision;
+    return docs.length > 0 && decision !== "pending" && decision !== "needs-doc";
+  });
+
+  const activeMeta = stepMeta[step];
+  const ActiveIcon = activeMeta.icon;
+
+  async function pullIngressBatch() {
+    setLoading("pull");
+    setErrorMessage(null);
+
+    const { data, error } = await client.POST("/api/import-flows/ingress/pull");
+
+    if (error || !data) {
+      setErrorMessage("Failed to pull ingress batch.");
+      setLoading(null);
+      return;
+    }
+
+    startTransition(() => {
+      setBatch(data);
+      setSelectedId(data.items[0]?.id ?? "");
+      setDraftDocs({});
+      setDraftNotes({});
+      setDraftDecision({});
+      setDraftName({});
+      setDraftCategory({});
+      setCommitResult(null);
+      setLoading(null);
+    });
+  }
+
+  async function runReasoningLayer() {
+    if (!batch) return;
+
+    setLoading("match");
+    setErrorMessage(null);
+
+    const { data, error } = await client.POST("/api/import-flows/{batchId}/match", {
+      params: { path: { batchId: batch.id } },
+    });
+
+    if (error || !data) {
+      setErrorMessage("Failed to run reasoning layer.");
+      setLoading(null);
+      return;
+    }
+
+    startTransition(() => {
+      setBatch(data);
+      setSelectedId(data.items[0]?.id ?? "");
+      setLoading(null);
+    });
+  }
+
+  function addDraftDoc() {
+    if (!selectedRow || !draftDocInput.trim()) return;
+
+    const nextDocs = [...(draftDocs[selectedRow.id] ?? selectedRow.documents.map((document) => document.title)), draftDocInput.trim()];
+    setDraftDocs((current) => ({ ...current, [selectedRow.id]: nextDocs }));
+    setDraftDocInput("");
+  }
+
+  async function submitReview() {
+    if (!batch) return;
+
+    const payload: ReviewPayload = {
+      items: rows.map((row) => ({
+        itemId: row.id,
+        technicianDecision: draftDecision[row.id] ?? row.technicianDecision === "pending" ? "confirmed" : (draftDecision[row.id] ?? row.technicianDecision),
+        technicianNotes: draftNotes[row.id] ?? row.technicianNotes ?? undefined,
+        normalizedName: draftName[row.id] ?? row.normalizedName ?? undefined,
+        category: draftCategory[row.id] ?? row.category ?? undefined,
+        documents: (draftDocs[row.id] ?? row.documents.map((document) => document.title)).map((title) => ({ title })),
+      })),
+    };
+
+    setLoading("review");
+    setErrorMessage(null);
+
+    const { data, error } = await client.POST("/api/import-flows/{batchId}/review", {
+      params: { path: { batchId: batch.id } },
+      body: payload,
+    });
+
+    if (error || !data) {
+      setErrorMessage("Failed to submit technician review.");
+      setLoading(null);
+      return;
+    }
+
+    startTransition(() => {
+      setBatch(data);
+      setSelectedId(data.items[0]?.id ?? "");
+      setDraftDocInput("");
+      setLoading(null);
+    });
+  }
+
+  async function commitImport() {
+    if (!batch) return;
+
+    setLoading("commit");
+    setErrorMessage(null);
+
+    const { data, error } = await client.POST("/api/import-flows/{batchId}/commit", {
