+                    <p className="mt-1 text-[13px] font-semibold text-white">{meta.title}</p>
+                  </div>
+                );
+              })}
+            </div>
+          </div>
+
+          <div className="mt-6 rounded-[22px] border border-white/[0.06] bg-[#0a0a0a]/80 p-4">
