+              </Button>
+            </div>
+
+            {commitResult && (
+              <div className="mt-4 rounded-[20px] border border-emerald-500/18 bg-emerald-500/[0.05] p-4 text-[13px] text-emerald-300">
+                Import batch committed. {commitResult.catalogEntries.length} catalog entries written through backend pipeline.
