Index: /Users/cllupo/Documents/GitHub/atlaaas/project-atlas/projects/frontend/src/pages/ops/ImportFlow.tsx
===================================================================
--- /Users/cllupo/Documents/GitHub/atlaaas/project-atlas/projects/frontend/src/pages/ops/ImportFlow.tsx
+++ /Users/cllupo/Documents/GitHub/atlaaas/project-atlas/projects/frontend/src/pages/ops/ImportFlow.tsx
@@ -0,0 +1,788 @@
+import {
+  BookOpenText,
+  Brain,
+  CheckCircle,
+  Database,
+  FileArrowUp,
+  PencilSimple,
+  SpinnerGap,
+  UserFocus,
+  WarningCircle,
+} from "@phosphor-icons/react";
+import { createPublicApiClient } from "@atlas/api-client";
+import type { components } from "@atlas/api-types";
+import { startTransition, type ReactNode, useMemo, useState } from "react";
+import { Button } from "@/components/ui/button";
+import { Input } from "@/components/ui/input";
+import { Progress } from "@/components/ui/progress";
+import { Textarea } from "@/components/ui/textarea";
+
+type WizardStep = 1 | 2 | 3 | 4;
+type BatchResponse = components["schemas"]["ImportBatchResponseDto"];
+type CommitResponse = components["schemas"]["CommitImportBatchResponseDto"];
+type ImportItem = components["schemas"]["ImportItemResponseDto"];
+type ReviewPayload = components["schemas"]["ReviewImportBatchDto"];
+type TechnicianDecision = components["schemas"]["ImportItemResponseDto"]["technicianDecision"];
+
+const client = createPublicApiClient();
+
+const stepMeta = {
+  1: {
+    eyebrow: "Step 1",
+    title: "Pull ingress batch",
+    description: "Source raw SKUs from ingress controller, not CSV upload.",
+    icon: FileArrowUp,
+    progress: 25,
+  },
+  2: {
+    eyebrow: "Step 2",
+    title: "Run reasoning layer",
+    description: "Use backend matching service through Vercel AI SDK to normalize and match parts.",
+    icon: Brain,
+    progress: 55,
+  },
+  3: {
+    eyebrow: "Step 3",
+    title: "Technician review",
+    description: "Attach docs and confirm or edit associations before unlock.",
+    icon: UserFocus,
+    progress: 82,
+  },
+  4: {
+    eyebrow: "Final",
+    title: "Confirmation table",
+    description: "Commit reviewed items into component catalog.",
+    icon: Database,
+    progress: 100,
+  },
+} as const;
+
+function Panel({ title, subtitle, children }: { children: ReactNode; subtitle: string; title: string }) {
+  return (
+    <section className="rounded-[24px] border border-white/[0.06] bg-[#0a0a0a] shadow-[inset_0_1px_0_rgba(255,255,255,0.04)]">
+      <div className="border-b border-white/[0.06] px-5 py-4">
+        <p className="text-[10px] uppercase tracking-[0.16em] text-zinc-600">{subtitle}</p>
+        <h2 className="mt-1 text-[18px] font-semibold text-white">{title}</h2>
+      </div>
+      <div className="px-5 py-5">{children}</div>
+    </section>
+  );
+}
+
+function getErrorMessage(error: unknown) {
+  if (error instanceof Error) return error.message;
+  return "Request failed";
+}
+
+export default function ImportFlow() {
+  const [step, setStep] = useState<WizardStep>(1);
+  const [batch, setBatch] = useState<BatchResponse | null>(null);
+  const [selectedId, setSelectedId] = useState("");
+  const [draftDocs, setDraftDocs] = useState<Record<string, string[]>>({});
+  const [draftDocInput, setDraftDocInput] = useState("");
+  const [draftNotes, setDraftNotes] = useState<Record<string, string>>({});
+  const [draftDecision, setDraftDecision] = useState<Record<string, TechnicianDecision>>({});
+  const [draftName, setDraftName] = useState<Record<string, string>>({});
+  const [draftCategory, setDraftCategory] = useState<Record<string, string>>({});
+  const [commitResult, setCommitResult] = useState<CommitResponse | null>(null);
+  const [errorMessage, setErrorMessage] = useState<string | null>(null);
+  const [loading, setLoading] = useState<"pull" | "match" | "review" | "commit" | null>(null);
+
+  const rows = batch?.items ?? [];
+  const selectedRow = useMemo(
+    () => rows.find((row) => row.id === selectedId) ?? rows[0] ?? null,
+    [rows, selectedId]
+  );
+
+  const step1Complete = Boolean(batch && batch.items.length > 0);
+  const step2Complete = rows.length > 0 && rows.every((row) => row.normalizedName && row.candidates.length > 0);
+  const step3Complete = rows.length > 0 && rows.every((row) => {
+    const docs = draftDocs[row.id] ?? row.documents.map((document) => document.title);
+    const decision = draftDecision[row.id] ?? row.technicianDecision;
+    return docs.length > 0 && decision !== "pending" && decision !== "needs-doc";
+  });
+
+  const activeMeta = stepMeta[step];
+  const ActiveIcon = activeMeta.icon;
+
+  async function pullIngressBatch() {
+    setLoading("pull");
+    setErrorMessage(null);
+
+    const { data, error } = await client.POST("/api/import-flows/ingress/pull");
+
+    if (error || !data) {
+      setErrorMessage("Failed to pull ingress batch.");
+      setLoading(null);
+      return;
+    }
+
+    startTransition(() => {
+      setBatch(data);
+      setSelectedId(data.items[0]?.id ?? "");
+      setDraftDocs({});
+      setDraftNotes({});
+      setDraftDecision({});
+      setDraftName({});
+      setDraftCategory({});
+      setCommitResult(null);
+      setLoading(null);
+    });
+  }
+
+  async function runReasoningLayer() {
+    if (!batch) return;
+
+    setLoading("match");
+    setErrorMessage(null);
+
+    const { data, error } = await client.POST("/api/import-flows/{batchId}/match", {
+      params: { path: { batchId: batch.id } },
+    });
+
+    if (error || !data) {
+      setErrorMessage("Failed to run reasoning layer.");
+      setLoading(null);
+      return;
+    }
+
+    startTransition(() => {
+      setBatch(data);
+      setSelectedId(data.items[0]?.id ?? "");
+      setLoading(null);
+    });
+  }
+
+  function addDraftDoc() {
+    if (!selectedRow || !draftDocInput.trim()) return;
+
+    const nextDocs = [...(draftDocs[selectedRow.id] ?? selectedRow.documents.map((document) => document.title)), draftDocInput.trim()];
+    setDraftDocs((current) => ({ ...current, [selectedRow.id]: nextDocs }));
+    setDraftDocInput("");
+  }
+
+  async function submitReview() {
+    if (!batch) return;
+
+    const payload: ReviewPayload = {
+      items: rows.map((row) => ({
+        itemId: row.id,
+        technicianDecision: draftDecision[row.id] ?? row.technicianDecision === "pending" ? "confirmed" : (draftDecision[row.id] ?? row.technicianDecision),
+        technicianNotes: draftNotes[row.id] ?? row.technicianNotes ?? undefined,
+        normalizedName: draftName[row.id] ?? row.normalizedName ?? undefined,
+        category: draftCategory[row.id] ?? row.category ?? undefined,
+        documents: (draftDocs[row.id] ?? row.documents.map((document) => document.title)).map((title) => ({ title })),
+      })),
+    };
+
+    setLoading("review");
+    setErrorMessage(null);
+
+    const { data, error } = await client.POST("/api/import-flows/{batchId}/review", {
+      params: { path: { batchId: batch.id } },
+      body: payload,
+    });
+
+    if (error || !data) {
+      setErrorMessage("Failed to submit technician review.");
+      setLoading(null);
+      return;
+    }
+
+    startTransition(() => {
+      setBatch(data);
+      setSelectedId(data.items[0]?.id ?? "");
+      setDraftDocInput("");
+      setLoading(null);
+    });
+  }
+
+  async function commitImport() {
+    if (!batch) return;
+
+    setLoading("commit");
+    setErrorMessage(null);
+
+    const { data, error } = await client.POST("/api/import-flows/{batchId}/commit", {
+      params: { path: { batchId: batch.id } },
+    });
+
+    if (error || !data) {
+      setErrorMessage("Failed to commit import batch.");
+      setLoading(null);
+      return;
+    }
+
+    startTransition(() => {
+      setCommitResult(data);
+      setBatch(data.batch);
+      setLoading(null);
+    });
+  }
+
+  return (
+    <div className="min-h-full bg-[#050505] px-4 py-4 md:px-6 md:py-5">
+      <div className="mx-auto flex max-w-[1500px] flex-col gap-4">
+        <section className="rounded-[28px] border border-white/[0.07] bg-[radial-gradient(circle_at_top_left,rgba(59,130,246,0.16),transparent_28%),radial-gradient(circle_at_78%_18%,rgba(16,185,129,0.12),transparent_24%),linear-gradient(180deg,#0d0d0d_0%,#070707_100%)] px-5 py-5 md:px-7 md:py-7">
+          <div className="flex flex-col gap-5 lg:flex-row lg:items-end lg:justify-between">
+            <div className="max-w-3xl">
+              <div className="mb-3 flex items-center gap-2">
+                <span className="rounded-full border border-emerald-500/20 bg-emerald-500/10 px-2.5 py-1 text-[10px] font-bold uppercase tracking-[0.18em] text-emerald-400">
+                  Typed API flow
+                </span>
+                <span className="text-[10px] uppercase tracking-[0.16em] text-zinc-600">
+                  @atlas/api-client
+                </span>
+              </div>
+
+              <h1 className="text-[28px] font-semibold leading-tight tracking-tight text-white md:text-[34px]">
+                Pull ingress SKUs, match through backend AI pipeline, then confirm and commit through typed Atlas API requests.
+              </h1>
+
+              <p className="mt-3 max-w-2xl text-[13px] leading-6 text-zinc-400 md:text-[14px]">
+                Frontend now uses generated OpenAPI types and Atlas API client instead of local-only mock workflow state.
+              </p>
+            </div>
+
+            <div className="grid grid-cols-2 gap-3 sm:grid-cols-4 lg:min-w-[520px]">
+              {([1, 2, 3, 4] as WizardStep[]).map((item) => {
+                const meta = stepMeta[item];
+                const Icon = meta.icon;
+                const active = step === item;
+                const done = item < step;
+
+                return (
+                  <div
+                    key={item}
+                    className={`rounded-[20px] border px-4 py-4 shadow-[inset_0_1px_0_rgba(255,255,255,0.04)] ${
+                      active
+                        ? "border-blue-500/30 bg-blue-500/[0.08]"
+                        : done
+                          ? "border-emerald-500/20 bg-emerald-500/[0.05]"
+                          : "border-white/[0.06] bg-[#0a0a0a]/90"
+                    }`}
+                  >
+                    <div className="mb-3 flex items-center justify-between">
+                      <span className={`rounded-2xl border border-white/[0.06] bg-black/20 p-2 ${active ? "text-blue-300" : done ? "text-emerald-300" : "text-zinc-300"}`}>
+                        <Icon size={16} weight="duotone" />
+                      </span>
+                      {done && <CheckCircle size={16} weight="fill" className="text-emerald-400" />}
+                    </div>
+                    <p className="text-[10px] uppercase tracking-[0.14em] text-zinc-600">{meta.eyebrow}</p>
+                    <p className="mt-1 text-[13px] font-semibold text-white">{meta.title}</p>
+                  </div>
+                );
+              })}
+            </div>
+          </div>
+
+          <div className="mt-6 rounded-[22px] border border-white/[0.06] bg-[#0a0a0a]/80 p-4">
+            <div className="flex items-start justify-between gap-4">
+              <div className="flex items-start gap-3">
+                <div className="rounded-2xl border border-white/[0.06] bg-black/20 p-2 text-blue-300">
+                  <ActiveIcon size={18} weight="duotone" />
+                </div>
+                <div>
+                  <p className="text-[10px] uppercase tracking-[0.14em] text-zinc-600">Current stage</p>
+                  <h2 className="mt-1 text-[18px] font-semibold text-white">{activeMeta.title}</h2>
+                  <p className="mt-1 text-[12px] text-zinc-500">{activeMeta.description}</p>
+                </div>
+              </div>
+
+              <div className="min-w-[180px]">
+                <div className="mb-2 flex items-center justify-between text-[11px] text-zinc-500">
+                  <span>Progress</span>
+                  <span>{activeMeta.progress}%</span>
+                </div>
+                <Progress value={activeMeta.progress} indicatorClassName="bg-blue-500" />
+              </div>
+            </div>
+          </div>
+        </section>
+
+        {errorMessage && (
+          <div className="rounded-[20px] border border-red-500/16 bg-red-500/[0.05] px-4 py-3 text-[13px] text-red-300">
+            {errorMessage}
