+                    disabled={!batch || loading === "match"}
+                    className="mt-4 h-10 w-full rounded-xl bg-white text-black hover:bg-zinc-100 disabled:bg-white/10 disabled:text-zinc-500"
+                  >
+                    {loading === "match" ? <SpinnerGap className="animate-spin" weight="bold" /> : <Brain weight="bold" />}
+                    Run reasoning layer
+                  </Button>
+                </div>
+              </div>
+
+              <div className="rounded-[22px] border border-white/[0.06] bg-white/[0.02] p-4">
+                {selectedRow ? (
+                  <>
+                    <div className="flex items-center gap-2 text-zinc-300">
+                      <Brain size={16} weight="duotone" />
+                      <h3 className="text-[15px] font-semibold text-white">Reasoned output</h3>
+                    </div>
+
+                    <div className="mt-4 grid gap-3 sm:grid-cols-2">
+                      <div>
+                        <p className="text-[10px] uppercase tracking-[0.14em] text-zinc-600">Normalized name</p>
+                        <div className="mt-2 rounded-[16px] border border-white/[0.06] bg-black/20 px-3 py-3 text-[12px] text-white">
+                          {selectedRow.normalizedName ?? "Not generated yet"}
+                        </div>
+                      </div>
+                      <div>
+                        <p className="text-[10px] uppercase tracking-[0.14em] text-zinc-600">Category</p>
+                        <div className="mt-2 rounded-[16px] border border-white/[0.06] bg-black/20 px-3 py-3 text-[12px] text-white">
